import React from 'react';
import { useParams } from 'react-router-dom';

const PetDetails = () => {
  const { id } = useParams();
  return (
    <div className="container">
      <h1>Pet Details</h1>
      <p>Viewing details for pet ID: {id}</p>
    </div>
  );
};

export default PetDetails;
